/**
 * Every failure carries the stable code shared by all QoreSign
 * implementations (for example `INVALID_MNEMONIC`) and a human-readable
 * detail. (The field is not named `message`: that clashes with
 * `Throwable.message` in the Kotlin bindings.)
 */
sealed class QoreSignException: kotlin.Exception() {
    
    class Failure(
        
        val `code`: kotlin.String, 
        
        val `detail`: kotlin.String
        ) : QoreSignException() {
        override val message
            get() = "code=${ `code` }, detail=${ `detail` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<QoreSignException> {
        override fun lift(error_buf: RustBuffer.ByValue): QoreSignException = FfiConverterTypeQoreSignError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeQoreSignError : FfiConverterRustBuffer<QoreSignException> {
    override fun read(buf: ByteBuffer): QoreSignException {
        

        return when(buf.getInt()) {
            1 -> QoreSignException.Failure(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: QoreSignException): ULong {
        return when(value) {
            is QoreSignException.Failure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: QoreSignException, buf: ByteBuffer) {
        when(value) {
            is QoreSignException.Failure -> {
                buf.putInt(1)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



